N,A,L,M,G='#0B1F3A','#2D7FF0','#5AA2FF','#CFE6F7','#EEF5FC'
V={
'calendar':f'<rect x="30" y="44" width="140" height="128" rx="24" fill="#fff"/><rect x="30" y="44" width="140" height="40" rx="24" fill="{A}"/><rect x="30" y="66" width="140" height="18" fill="{A}"/><rect x="62" y="30" width="12" height="30" rx="6" fill="{N}"/><rect x="126" y="30" width="12" height="30" rx="6" fill="{N}"/>'+''.join(f'<circle cx="{58+i*28}" cy="{106+j*26}" r="6" fill="{M}"/>' for j in range(3) for i in range(4) if not (i==2 and j==1))+f'<circle cx="114" cy="132" r="16" fill="{N}"/><path d="M107 132l5 5 9-10" stroke="#fff" stroke-width="5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
'clock':f'<circle cx="100" cy="104" r="72" fill="{A}"/><circle cx="100" cy="104" r="56" fill="#fff"/>'+''.join(f'<circle cx="{100+46*__import__("math").cos(k*0.5236)}" cy="{104+46*__import__("math").sin(k*0.5236)}" r="{4 if k%3==0 else 2.5}" fill="{M if k%3 else N}"/>' for k in range(12))+f'<path d="M100 104V70M100 104l24 14" stroke="{N}" stroke-width="8" stroke-linecap="round"/><circle cx="100" cy="104" r="8" fill="{A}"/>',
'zoom':f'<path d="M122 122l40 40" stroke="{A}" stroke-width="22" stroke-linecap="round"/><circle cx="88" cy="88" r="56" fill="{M}"/><circle cx="88" cy="88" r="56" fill="none" stroke="{N}" stroke-width="14"/><path d="M60 78a30 30 0 0 1 22-22" stroke="#fff" stroke-width="9" fill="none" stroke-linecap="round"/>',
'chat':f'<path d="M30 52a24 24 0 0 1 24-24h76a24 24 0 0 1 24 24v44a24 24 0 0 1-24 24H74l-28 22v-22a24 24 0 0 1-16-22z" fill="{A}"/>'+''.join(f'<circle cx="{70+i*22}" cy="74" r="7" fill="#fff"/>' for i in range(3))+f'<path d="M96 118h52a22 22 0 0 1 22 22v18l0 22-20-16h-54a22 22 0 0 1-22-22v-2z" fill="{M}"/>',
'bell':f'<path d="M100 32a50 50 0 0 1 50 50v34l16 22H34l16-22V82a50 50 0 0 1 50-50z" fill="{A}"/><circle cx="100" cy="156" r="16" fill="{N}"/><path d="M72 84a28 28 0 0 1 18-26" stroke="#fff" stroke-width="8" fill="none" stroke-linecap="round" opacity=".7"/><circle cx="150" cy="50" r="16" fill="#FA5F6D"/>',
'tick':f'<circle cx="100" cy="100" r="70" fill="{A}"/><path d="M68 102l22 22 44-46" stroke="#fff" stroke-width="16" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
'mobile':f'<rect x="56" y="22" width="88" height="160" rx="22" fill="{N}"/><rect x="64" y="34" width="72" height="136" rx="14" fill="{G}"/><rect x="72" y="50" width="56" height="34" rx="8" fill="{M}"/><rect x="72" y="92" width="40" height="7" rx="3.5" fill="{N}" opacity=".7"/><rect x="72" y="104" width="52" height="7" rx="3.5" fill="{M}"/><rect x="72" y="140" width="56" height="18" rx="9" fill="{A}"/>',
'computer':f'<rect x="22" y="40" width="156" height="120" rx="18" fill="#fff"/><path d="M22 58a18 18 0 0 1 18-18h120a18 18 0 0 1 18 18v6H22z" fill="{M}"/>'+''.join(f'<circle cx="{38+i*12}" cy="52" r="4" fill="{A if i==0 else N}" opacity="{1 if i==0 else .35}"/>' for i in range(3))+f'<rect x="40" y="80" width="70" height="10" rx="5" fill="{N}"/><rect x="40" y="98" width="96" height="7" rx="3.5" fill="{M}"/><rect x="40" y="124" width="62" height="20" rx="10" fill="{A}"/>',
'heart':f'<path d="M100 170C40 128 24 100 24 74a38 38 0 0 1 76-8 38 38 0 0 1 76 8c0 26-16 54-76 96z" fill="{A}"/><path d="M40 100h34l10-20 16 40 12-30 8 10h40" stroke="#fff" stroke-width="8" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
'plus':f'<rect x="80" y="28" width="40" height="144" rx="20" fill="{A}"/><rect x="28" y="80" width="144" height="40" rx="20" fill="{A}"/>',
'shield':f'<path d="M100 24l64 24v48c0 40-28 68-64 82-36-14-64-42-64-82V48z" fill="{A}"/><path d="M100 24l64 24v48c0 40-28 68-64 82z" fill="{N}" opacity=".18"/><path d="M72 100l20 20 38-40" stroke="#fff" stroke-width="14" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
'star':f'<path d="M100 24l22 46 50 6-37 34 10 50-45-25-45 25 10-50-37-34 50-6z" fill="{A}" stroke="{A}" stroke-width="10" stroke-linejoin="round"/>',
}
names=list(V)
def page(title,sub,cell):
    return f'''<html><head><link rel="stylesheet" href="base.css"><style>html,body{{margin:0;width:1600px!important;height:1000px!important;overflow:hidden}}.pg{{width:1600px;height:1000px;background:{G};font-family:Poppins;position:relative;overflow:hidden}}
h1{{position:absolute;left:90px;top:60px;margin:0;font-weight:300;font-size:54px;color:{N};letter-spacing:-1.5px}} h1 b{{font-weight:700;color:{A}}}
p{{position:absolute;left:92px;top:140px;margin:0;font-size:20px;color:{N};opacity:.6;font-weight:300}}
.g{{position:absolute;left:90px;top:230px;display:grid;grid-template-columns:repeat(6,220px);gap:24px 0}}
.c{{width:200px;height:200px;background:#fff;border:2px solid #E2EAF4;border-radius:36px;display:flex;align-items:center;justify-content:center}}
.c img,.c svg{{width:160px;height:160px;object-fit:contain}}</style></head><body><div class="pg"><h1>{title}</h1><p>{sub}</p><div class="g">{''.join('<div class="c">'+cell(n)+'</div>' for n in names)}</div></div></body></html>'''
open('el-a.html','w').write(page('Opção A · <b>3D branco</b>','Ícones 3D baixados do 3dicons.co, estilo clay, fundo recortado.',lambda n:f'<img src="{n}_clay.png">'))
open('el-b.html','w').write(page('Opção B · <b>3D azul</b>','Os mesmos 3D, recoloridos no azul e navy da marca.',lambda n:f'<img src="{n}_blue.png">'))
open('el-c.html','w').write(page('Opção C · <b>vetor 2D</b>','Desenhados do zero no estilo da marca: flat, cantos arredondados, sem sombra.',lambda n:f'<svg viewBox="0 0 200 200">{V[n]}</svg>'))
